Ext.define('BNK.view.HumanResource.hrd.HrdCrsRept71MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.HrdCrsRept71MViewController',

    config: {
        command: null,
        aprHistId: null,
        record: null,
        viewId: 'HrdCrsRept71M'
    },

    /* 내부함수 / 폼 컴포넌트 초기화 */
    fnInitComponentForm: function(form) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            fields = form.getFields();

        for (var key in fields) {
            var item = fields[key];

            if (item.isXType('displayfield')) {
                continue;
            }

            item.setEditable(false);
            item.setReadOnly(true);
            //change 이벤트가 있는 아이템들 이벤트 삭제하기
            if (item && item.events.change) {
                item.suspendEvents(true);
            }
        }

        //첨부파일 존재 시 downloadBtn 활성화
        if(!Ext.isEmpty(refs.atchFileNm.getValue()) &&
           !Ext.isEmpty(refs.atchFileId.getValue()) &&
           !Ext.isEmpty(refs.atchFileParentId.getValue())){
            refs.downloadBtn.setDisabled(false);
        }
        else {
            refs.downloadBtn.setDisabled(true);
        }
    },

    settingValues: function(config, docData) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        /** [필독]
             *  AS_IS 공통 결재 로직
             *    - 신청서에 출력될 정보를 DOC_DATA 에 JSON 형식으로 저장하고
             *    , 추후 출력할땐 DOC_DATA에 저장된 데이터를 가지고 출력을 한다.
             *     단점 : 유지보수가 너무 힘들다 [ 데이터의 수정이 있어야할때 , JSON replace 를 해야한다.]
             *           계좌번호등 암호화가 필요한 중요정보에 대한 따로 처리가 필요함.
             *  TO_BE 공통 결재 로직
             *    - 기안시에는 DOC_DATA 에 JSON 형식으로 저장하되 [-> 추후 문제있을시 이력으로 사용]
             *     , 추후 출력할땐 업무단 SVC에서 데이터를 조회하여 출력이 되도록 한다.
             * */
        //ApprovalBoxSvc 공통에서 command 로 구분함.
        if (config.command === Constants.sanction.DRAFT) { // 기안(01) 시 설정
            vm.set('docData', docData);
        } else {
            var comAprHistId = config.aprHistId;
            if (comAprHistId) {
                var params = {
                    hrHrpmCompId : SecurityUtils.getPrincipal().hrHrpmCompId,
                    comAprHistId : comAprHistId,
                };
                /*상세항목 조회*/
                Ext.Ajax.request({
                    headers : {
                        serviceId : 'HrdCrsSvc.findAllHrdCrsReptDetail',
                        viewId : me.getViewId(),
                        scope : me,
                    },
                    jsonData : params,
                    success : function(response , me) {
                        var res = Ext.JSON.decode(response.responseText);
                        refs.frmDetail.setValues(res.result);
                    }
                }, me);
            }

        }


    },

    onClickDraft: function() {
        // 결재선 [기안] 처리
        var me               = this,
            vm               = me.getViewModel(),
            refs             = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid,
            aprHistId        =  me.getAprHistId();


        // 결재선 [기안] 처리
        ApprovalBoxSvc.draft({
            scope                 : me,
            edocCd                : vm.get('docCd'),				 	 // 전자문서관리에서 설정된 문서코드: 화면ID를 사용함
            docNm                 : vm.get('docNm'), 							 // 문서명
            bizDvcd               : 'HRD', 							 // 업무구분코드
            bizServiceId          : 'HrdCrsSvc.saveHrdCrsRept', 	 // 연관 업무서비스ID
            aprHistId             : aprHistId,						 	 // 결재이력ID
            approvalLineRecords   : approvalLineGrid.getJsonAllRecords(), // 결재선 그리드 데이터
            record : me.getRecord(),
            docData               : {								 // 결재문서 데이터
                fieldValues       : vm.get('fieldValues'),
                beforechange      : null,
                afterchange       : vm.get('afterchange') 			 // 결재문서 필드값
            },

        });

    },

    /* [결재] 버튼 */
    onClickSanction: function() {
        //Ext.Msg.confirm('결재', '결재 처리하시겠습니까?' , this.sanction, this);

        this.sanction();
    },

    sanction: function() {
        //if(btn === 'no') return false;

        var me               = this,
            vm               = me.getViewModel(),
            refs             = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid;


        ApprovalBoxSvc.sanction({
            aprHistId : me.getAprHistId(), // 결재이력ID
            record : me.getRecord(), // 동시성 제어를 하기 위해 사용
            approvalLineRecords : refs.approvalLineGrid.getJsonAllRecords(),
            scope : me
        });

    },

    /* 반송 버튼 탭 이벤트 */
    onClickSendBack: function() {
        //Ext.Msg.confirm('반송', '반송 처리하시겠습니까?' , this.sendBack, this);

        this.sendBack();
    },

    sendBack: function(btn, text) {
        if(btn === 'no') return false;

        var me               = this,
            vm               = me.getViewModel(),
            refs             = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid;


        // 결재선 [반송] 처리
        ApprovalBoxSvc.sendBack({
            scope                 : me,
            approvalLineRecords   : approvalLineGrid.getJsonAllRecords(), // 결재선 그리드 데이터
            aprHistId : me.getAprHistId(), 		// 결재이력ID
            record : me.getRecord(),
        });

    },

    /* 회수 버튼 탭 버튼 */
    onClickWithdrawal: function() {
        //Ext.Msg.confirm('회수', '회수 처리하시겠습니까?' , this.withDrawal, this);

        this.withDrawal();
    },

    withDrawal: function(btn, text) {
        if(btn === 'no') return false;

        var me               = this,
            vm               = me.getViewModel(),
            refs             = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid;


        // 결재선 [회수] 처리
        ApprovalBoxSvc.withdrawal({
            scope                 : me,
            approvalLineRecords   : approvalLineGrid.getJsonAllRecords(), // 결재선 그리드 데이터
            aprHistId 			  : me.getAprHistId(), 						// 결재이력ID
            record 				  : me.getRecord(),
        });

    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid, 	// 결재선
            afterchangeform = refs.frmDetail,
            initialConfig = component.config, 			// 화면초기데이터
            aprHistId = initialConfig.aprHistId, 		// 결재내역ID
            command = initialConfig.command,
            aprHistData = initialConfig.aprHistData, 	// 결재이력데이터
            // 결재함(ExpNteApr02)에서는 docData,
            // 연수보고(HrdCrsInfo01)에서는 aprHistData.docData
            docData = (aprHistData) ? aprHistData.docData : initialConfig.docData, 				// 문서데이터
            afterchange = docData.afterchange,
            record = initialConfig.record, 				// 결재함 목록에서 선택한 레코드
            edocCd = 'HrdCrsRept71',					// 문서코드
            edocNm = '연수보고서',
            userId = SecurityUtils.getPrincipal().hrHrpmEmpId; // 사용자ID

            vm.set('docCd', edocCd);
        vm.set('docNm', edocNm);
        vm.set('aprHistId', aprHistId);
        vm.set('record', record);
        vm.set('command', command);
        vm.set('docData', docData);

        me.setAprHistId(aprHistId); // 결재이력아이디
        me.setRecord(record); // 동시성 제어를 하기 위한 용도로 Config에 저장함
        me.setCommand(command); // 결재처리 커맨드

        // 결재문서 초기화 설정
        ApprovalBoxSvc.setup({
            command : command, 		// 결재선구분커맨드
            viewModel : vm,
            edocCd : edocCd, 		// 전자문서관리화면에 설정된 문서코드: 화면ID를 사용
            aprHistId : aprHistId, 	// 결재이력ID
            scope : me
        });

        afterchange.sttnStrdtHiphone = DateUtils.parseDate(afterchange.sttnStrdt).substr(0,10);		// 연수시작일자
        afterchange.sttnEdtHiphone = DateUtils.parseDate(afterchange.sttnEdt).substr(0,10);		// 연수종료일자
        afterchange.aplDvcdNm = CodeUtils.getText('HWM009', afterchange.aplDvcd);			// 신청구분 (HWM009)
        afterchange.stcdNm = CodeUtils.getText('INB014', afterchange.stcd);			// 상태 (INB014)
        afterchange.aplStcdNm = CodeUtils.getText('INB025', afterchange.aplStcd);			// 결재상태 (INB025)
        vm.set('detail', afterchange);
        afterchangeform.setValues(vm.get('detail'));
        vm.set('afterchange', afterchange);				// formData


        var rgdt = (aprHistData) ? record.reptDt : record.fstRgDtti;		// 연수보고(sttnReptDt) , 결재함(fstRgDtti)
        refs.rgdt.setHtml(DateUtils.parseDate(rgdt).substr(0,10));

        me.fnInitComponentForm(afterchangeform);

        me.settingValues(initialConfig, docData);
    },

    onBtnDownTap: function(button, e, eOpts) {
        //파일 다운로드
        if (button.up('#atchFile').down('#atchFileId').getValue()) {
            var _url = Property.BASE_URL + Property.DOWN_URL + button.up('#atchFile').down('#atchFileId').getValue();
            var form = document.createElement("form");
            form.setAttribute("method", "get");
            form.setAttribute("action", _url);
            form.setAttribute("target", "_blank");

            if(!Ext.os.is.Android) {
                // iOS일 경우 safari로 다운로드 처리
                window.open(_url, '_system');
            } else {
                document.body.appendChild(form);
                form.submit();
                document.body.removeChild(form);
            }
        }
    }

});